      linearWebhookSecret: 'secret',
      discordWebhookUrl: 'https://discord.com/api/webhooks/123/token',
      fetch,
    };

    const result = await handle(payload, config);

    expect(calls).toHaveLength(1);
    expect(calls[0].method).toBe('POST');
    expect(calls[0].url).toBe('https://discord.com/api/webhooks/123/token');
    expect(calls[0].json).toEqual({
      content: 'Linear issue issue-123 closed\n\nComments:\n- Alice: First comment\n- Bob: Second comment',
    });
    expect(result).toEqual({
      discordMessageId: 'msg-456',
      channelId: 'chan-789',
      content: 'Linear issue issue-123 closed\n\nComments:\n- Alice: First comment\n- Bob: Second comment',
    });
  });

  it('uses injected fetch from config', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      jsonResponse({ id: 'm1', channel_id: 'c1', content: 'x', timestamp: 't' }, 200),
    );
