    const payload = { action: 'update', type: 'Issue', data: { state: { name: 'Closed' } } } as LinearWebhookPayload;
    await expect(handle(payload, { linearWebhookSecret: 's', discordWebhookUrl: 'https://discord.com/api/webhooks/1/2', fetch })).rejects.toThrow(
      'Invalid payload: data.id is required',
    );
