    const { fetch, calls } = fakeFetch((req) =>
      jsonResponse({ id: 'm1', channel_id: 'c1', content: 'Linear issue i1 closed\n\nNo comments.', timestamp: 't' }, 200),
    );
    const payload: LinearWebhookPayload = {
      action: 'update',
      type: 'Issue',
      data: { id: 'i1', state: { name: 'Closed' } },
      comments: [],
    };
    const result = await handle(payload, { linearWebhookSecret: 's', discordWebhookUrl: 'https://discord.com/api/webhooks/1/2', fetch });
    expect(calls[0].json).toEqual({ content: 'Linear issue i1 closed\n\nNo comments.' });
    expect(result.content).toBe('Linear issue i1 closed\n\nNo comments.');
