const MAX_DISCORD_CONTENT_LENGTH = 2000;

function formatDigest(issueId: string, comments: LinearComment[]): string {
  const header = `Linear issue ${issueId} closed`;
  if (comments.length === 0) {
    return `${header}\n\nNo comments.`;
  }
  const commentLines = comments.map((c) => `- ${c.author.name}: ${c.body}`);
  let digest = `${header}\n\nComments:\n${commentLines.join('\n')}`;
  if (digest.length > MAX_DISCORD_CONTENT_LENGTH) {
    digest = digest.slice(0, MAX_DISCORD_CONTENT_LENGTH - 3) + '...';
  }
  return digest;
}

function validatePayload(payload: LinearWebhookPayload): void {
  if (!payload.action || payload.action !== 'update') {
    throw new Error('Invalid payload: action must be "update"');
  }
  if (!payload.type || payload.type !== 'Issue') {
    throw new Error('Invalid payload: type must be "Issue"');
  }
  if (!payload.data?.id) {
    throw new Error('Invalid payload: data.id is required');
  }
  if (!payload.data?.state?.name || payload.data.state.name !== 'Closed') {
    throw new Error('Invalid payload: data.state.name must be "Closed"');
  }
}

export async function handle(
  payload: LinearWebhookPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  validatePayload(payload);

  const issueId = payload.data.id;
  const comments = payload.comments ?? [];
  const content = formatDigest(issueId, comments);

  const fetchImpl = config.fetch ?? fetch;
  const response = await fetchImpl(config.discordWebhookUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ content }),
  });

  if (!response.ok) {
    throw new Error(
      `Discord webhook request failed: ${response.status} ${response.statusText} at ${config.discordWebhookUrl}`,
    );
  }

  const data = (await response.json()) as {
    id: string;
    channel_id: string;
    content: string;
    timestamp: string;
  };

  return {
    discordMessageId: data.id,
    channelId: data.channel_id,
    content: data.content,
  };
}

